JS_SCHEME_RE = re.compile(r"(?i)(?P<prefix>^|[\s,])(?:javascript|vbscript)\s*:")
STYLE_EXPR_RE = re.compile(r"(?i)expression\s*\(")


def strip_js_schemes(value: str) -> str:
    def repl(match: re.Match) -> str:
        return match.group("prefix")

    return JS_SCHEME_RE.sub(repl, value)


def sanitize_style(value: str) -> str:
