def find_tag_end(text: str, start: int) -> int:
    in_quote = None
    i = start
    while i < len(text):
        ch = text[i]
        if in_quote:
            if ch == in_quote:
                in_quote = None
        else:
            if ch in ('"', "'"):
                in_quote = ch
            elif ch == ">":
                return i
        i += 1
    return -1


def is_script_tag_start(text: str, index: int) -> bool:
    if not text.startswith("<", index):
        return False
    end = index + 1 + len("script")
    if end > len(text):
        return False
    if text[index + 1:end].lower() != "script":
        return False
    if end == len(text):
        return True
    next_char = text[end]
    return next_char.isspace() or next_char in "/>"


def remove_script_blocks(html: str) -> str:
