    result: List[str] = []
    i = 0
    while i < len(html):
        idx = lower_html.find("<script", i)
        if idx == -1:
            result.append(html[i:])
            break
        if not is_script_tag_start(html, idx):
            result.append(html[i:idx + 1])
            i = idx + 1
            continue
        result.append(html[i:idx])
        open_end = find_tag_end(html, idx + 1)
        if open_end == -1:
            break
        open_tag = html[idx:open_end + 1]
        if re.search(r"/\s*>\s*$", open_tag):
            i = open_end + 1
            continue
        close_start = lower_html.find("</script", open_end + 1)
        if close_start == -1:
            break
        close_end = find_tag_end(html, close_start + 2)
        if close_end == -1:
            break
        i = close_end + 1
    return "".join(result)


def apply_edits(text: str, edits: List[Tuple[int, int, str]]) -> str:
    if not edits:
        return text
    edits_sorted = sorted(edits, key=lambda e: e[0], reverse=True)
    for start, end, replacement in edits_sorted:
        text = text[:start] + replacement + text[end:]
    return text


def sanitize_tag(tag: str) -> str:
