                quote = tag[i]
                i += 1
                val_start = i
                while i < len(tag) and tag[i] != quote:
                    i += 1
                val_end = i
                if i < len(tag) and tag[i] == quote:
                    i += 1
                value_span = (val_start, val_end, quote)
            else:
