def sanitize_html(html: str) -> str:
    html = remove_script_blocks(html)
    output: List[str] = []
    i = 0
    while i < len(html):
        lt = html.find("<", i)
        if lt == -1:
            output.append(html[i:])
            break
        output.append(html[i:lt])
        if lt + 1 >= len(html):
            output.append("<")
            break
        next_char = html[lt + 1]
        if not (next_char.isalpha() or next_char in "/!?"):
            output.append("<")
            i = lt + 1
            continue
        if html.startswith("<!--", lt):
            end = html.find("-->", lt + 4)
            if end == -1:
                output.append(html[lt:])
                break
            output.append(html[lt:end + 3])
