        if end == -1:
            output.append(html[lt:])
            break
        tag = html[lt:end + 1]
        output.append(sanitize_tag(tag))
        i = end + 1
    return "".join(output)


def main() -> int:
    if len(sys.argv) < 2:
        return 1
    path = sys.argv[1]
    with open(path, "rb") as handle:
        raw = handle.read()
    text = raw.decode("latin-1")
    sanitized = sanitize_html(text)
    if sanitized != text:
        with open(path, "wb") as handle:
            handle.write(sanitized.encode("latin-1"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
